#[path = "solution.rs"]
mod solution;

use solution::{create_rule, ordered_rules, update_rule, Channel, NoticeRule, RuleError, RulePatch};

fn channel_code(channel: &Channel) -> u8 {
    match channel {
        Channel::Email => 1,
        Channel::Sms => 2,
        Channel::Dashboard => 3,
    }
}

fn snapshot(rule: &NoticeRule) -> (u64, Vec<u8>, String, Option<u32>, Option<Vec<String>>) {
    (
        rule.id,
        rule.channels.iter().map(channel_code).collect(),
        rule.subject_prefix.clone(),
        rule.expires_after,
        rule.tags.clone(),
    )
}

#[test]
fn create_rule_preserves_prefix_and_initializes_optional_fields_empty() {
    let rule = create_rule(7, vec![Channel::Email, Channel::Dashboard], "  Alert:  ".to_string()).unwrap();
    assert_eq!(rule.id, 7);
    assert_eq!(rule.channels.iter().map(channel_code).collect::<Vec<_>>(), vec![1, 3]);
    assert_eq!(rule.subject_prefix, "  Alert:  ");
    assert!(rule.expires_after.is_none());
    assert!(rule.tags.is_none());
}

#[test]
fn create_rule_rejects_each_malformed_input() {
    assert!(matches!(create_rule(0, vec![Channel::Email], "x".to_string()), Err(RuleError::InvalidId)));
    assert!(matches!(create_rule(1, Vec::new(), "x".to_string()), Err(RuleError::NoChannels)));
    assert!(matches!(create_rule(1, vec![Channel::Sms], " \t\n".to_string()), Err(RuleError::EmptyPrefix)));
}

#[test]
fn tri_state_patch_preserves_sets_and_clears_fields() {
    let mut rule = create_rule(1, vec![Channel::Sms], "Notice".to_string()).unwrap();

    update_rule(&mut rule, RulePatch {
        expires_after: Some(Some(30)),
        tags: Some(Some(vec!["urgent".to_string(), " ops ".to_string()])),
    }).unwrap();
    assert_eq!(rule.expires_after, Some(30));
    assert_eq!(rule.tags.as_ref().unwrap(), &vec!["urgent".to_string(), " ops ".to_string()]);

    update_rule(&mut rule, RulePatch { expires_after: None, tags: None }).unwrap();
    assert_eq!(rule.expires_after, Some(30));
    assert!(rule.tags.is_some());

    update_rule(&mut rule, RulePatch {
        expires_after: Some(None),
        tags: Some(None),
    }).unwrap();
    assert!(rule.expires_after.is_none());
    assert!(rule.tags.is_none());

    update_rule(&mut rule, RulePatch {
        expires_after: None,
        tags: Some(Some(Vec::new())),
    }).unwrap();
    assert_eq!(rule.tags, Some(Vec::new()));
}

#[test]
fn invalid_patch_is_atomic() {
    let mut rule = create_rule(12, vec![Channel::Email, Channel::Sms], "Prefix".to_string()).unwrap();
    update_rule(&mut rule, RulePatch {
        expires_after: Some(Some(15)),
        tags: Some(Some(vec!["existing".to_string()])),
    }).unwrap();
    let before = snapshot(&rule);

    let result = update_rule(&mut rule, RulePatch {
        expires_after: Some(Some(0)),
        tags: Some(Some(vec!["replacement".to_string()])),
    });
    assert!(matches!(result, Err(RuleError::ZeroExpiry)));
    assert_eq!(snapshot(&rule), before);

    let result = update_rule(&mut rule, RulePatch {
        expires_after: Some(Some(99)),
        tags: Some(Some(vec!["valid".to_string(), " \n ".to_string()])),
    });
    assert!(matches!(result, Err(RuleError::EmptyTag)));
    assert_eq!(snapshot(&rule), before);
}

fn rule(id: u64, prefix: &str) -> NoticeRule {
    create_rule(id, vec![Channel::Dashboard], prefix.to_string()).unwrap()
}

#[test]
fn ordered_rules_is_stable_and_does_not_mutate_input() {
    let rules = vec![rule(3, "first-three"), rule(1, "one"), rule(3, "second-three"), rule(2, "two")];
    let before: Vec<(u64, String)> = rules.iter().map(|r| (r.id, r.subject_prefix.clone())).collect();

    let ordered = ordered_rules(&rules);
    assert_eq!(ordered.iter().map(|r| r.id).collect::<Vec<_>>(), vec![1, 2, 3, 3]);
    assert_eq!(ordered[2].subject_prefix, "first-three");
    assert_eq!(ordered[3].subject_prefix, "second-three");
    assert!(std::ptr::eq(ordered[2], &rules[0]));
    assert!(std::ptr::eq(ordered[3], &rules[2]));

    let after: Vec<(u64, String)> = rules.iter().map(|r| (r.id, r.subject_prefix.clone())).collect();
    assert_eq!(after, before);
    assert!(ordered_rules(&[]).is_empty());
}

